def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_index, id, qty)
    sell_book = []  # list of (price, arrival_index, id, qty)
    order_map = {}  # id -> (side, price, qty, arrival_index) for resting orders
    arrival_index = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, idx = order_map[order_id]
                del order_map[order_id]
                if side == 'buy':
                    buy_book = [(p, ai, oid, q) for p, ai, oid, q in buy_book if oid != order_id]
                else:
                    sell_book = [(p, ai, oid, q) for p, ai, oid, q in sell_book if oid != order_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3]
            price = order[4] if order_type != 'market' else None

            if side == 'buy':
                # Match against sell_book
                while qty > 0 and sell_book:
                    sell_book.sort(key=lambda x: (x[0], x[1]))  # sort by price asc, then arrival

                    if order_type == 'market':
                        match_price = sell_book[0][0]
                    else:
                        if sell_book[0][0] > price:
                            break
                        match_price = sell_book[0][0]

                    sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, match_price, trade_qty])

                    qty -= trade_qty
                    sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

                    if sell_book[0][3] == 0:
                        sell_book.pop(0)
                        if sell_id in order_map:
                            del order_map[sell_id]
                    else:
                        if sell_id in order_map:
                            order_map[sell_id] = ('sell', sell_price, sell_book[0][3], sell_arrival)

                # Rest remaining qty if limit or ioc with qty left
                if qty > 0 and order_type == 'limit':
                    buy_book.append((price, arrival_index, order_id, qty))
                    order_map[order_id] = ('buy', price, qty, arrival_index)
            else:  # sell
                # Match against buy_book
                while qty > 0 and buy_book:
                    buy_book.sort(key=lambda x: (-x[0], x[1]))  # sort by price desc, then arrival

                    if order_type == 'market':
                        match_price = buy_book[0][0]
                    else:
                        if buy_book[0][0] < price:
                            break
                        match_price = buy_book[0][0]

                    buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]

                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, match_price, trade_qty])

                    qty -= trade_qty
                    buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

                    if buy_book[0][3] == 0:
                        buy_book.pop(0)
                        if buy_id in order_map:
                            del order_map[buy_id]
                    else:
                        if buy_id in order_map:
                            order_map[buy_id] = ('buy', buy_price, buy_book[0][3], buy_arrival)

                # Rest remaining qty if limit with qty left
                if qty > 0 and order_type == 'limit':
                    sell_book.append((price, arrival_index, order_id, qty))
                    order_map[order_id] = ('sell', price, qty, arrival_index)

        arrival_index += 1

    return trades

